mkdir -p $STACK_WORKDIR/opencode-probe-v2/tmp/rational-numbers/opencode && cat > $STACK_WORKDIR/opencode-probe-v2/tmp/rational-numbers/opencode/ExpProbe.java <<'EOF'
public class ExpProbe {
    public static void main(String[] args) {
        double x = 8.0, a = 4, b = 3;
        double r1 = Math.pow(Math.pow(x, a), 1.0 / b);
        double r2 = Math.pow(Math.pow(x, 1.0 / b), a);
        double r3 = Math.pow(x, a / b);
        double r4 = Math.pow(x, (double) a / b);
        System.out.println("root(x^a,b)      = " + r1);
        System.out.println("(root(x,b))^a    = " + r2);
        System.out.println("x^(a/b int div)  = " + r3);
        System.out.println("x^((double)a/b)  = " + r4);
        // second test case: 9^(-1/2)
        System.out.println("9^(-1/2) r1 = " + Math.pow(Math.pow(9.0, -1), 1.0 / 2));
        System.out.println("9^(-1/2) r2 = " + Math.pow(Math.pow(9.0, 1.0 / 2), -1));
        System.out.println("9^(-1/2) r4 = " + Math.pow(9.0, (double) -1 / 2));
    }
}
EOF
